#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEM 10
static int parent[MAX_ELEM];
static int rank_[MAX_ELEM];

static void ds_init(void) {
    for (int i = 0; i < MAX_ELEM; ++i) {
        parent[i] = i;
        rank_[i] = 0;
    }
}

static int ds_find(int x) {
    if (parent[x] != x)
        parent[x] = ds_find(parent[x]);
    return parent[x];
}

static void ds_union(int a, int b) {
    int ra = ds_find(a);
    int rb = ds_find(b);
    if (ra == rb) return;
    if (rank_[ra] < rank_[rb]) {
        parent[ra] = rb;
    } else if (rank_[ra] > rank_[rb]) {
        parent[rb] = ra;
    } else {
        parent[rb] = ra;
        rank_[ra]++;
    }
}

static int parse_index(const char *s, int *out) {
    char *endptr;
    long v = strtol(s, &endptr, 10);
    if (*endptr != '\0' || v < 0 || v >= MAX_ELEM) return 0;
    *out = (int)v;
    return 1;
}

int main(int argc, char **argv) {
    ds_init();
    if (argc == 1) {
        puts("NOOP");
        return 0;
    }
    for (int i = 1; i < argc; ) {
        const char *cmd = argv[i];
        if (strcmp(cmd, "UNION") == 0) {
            if (i + 2 >= argc) { puts("INVALID"); break; }
            int a, b;
            if (!parse_index(argv[i+1], &a) || !parse_index(argv[i+2], &b)) {
                puts("INVALID");
            } else {
                ds_union(a, b);
                printf("UNION %d %d\n", a, b);
            }
            i += 3;
        } else if (strcmp(cmd, "FIND") == 0) {
            if (i + 1 >= argc) { puts("INVALID"); break; }
            int a;
            if (!parse_index(argv[i+1], &a)) {
                puts("INVALID");
            } else {
                int rep = ds_find(a);
                printf("FIND %d=%d\n", a, rep);
            }
            i += 2;
        } else if (strcmp(cmd, "NOOP") == 0) {
            puts("NOOP");
            i += 1;
        } else {
            puts("INVALID");
            i += 1;
        }
    }
    return 0;
}
